package engine;

/**
 * Represents an event generated by the order matching engine.
 *
 * @param type           type of event
 * @param orderID        ID of the order associated with the event
 * @param counterpartyId maker order ID for TRADE events, 0 otherwise
 * @param price          price associated with the event
 * @param quantity       quantity associated with the event
 */
public record Event(
        Type type,
        long orderID,
        long counterpartyId, // maker for TRADE, 0 for other types
        long price,
        long quantity) {

    /**
     * Defines the types of events produced by the matching engine.
     */
    public enum Type {
        ACCEPTED,
        TRADE,
        CANCELLED,
        REJECTED
    }

    /**
     * Creates an event indicating that an order was accepted.
     *
     * @param orderID order ID
     * @param price   order price
     * @param qty     accepted quantity
     * @return an ACCEPTED event
     */
    static Event accepted(long orderID, long price, long qty) {
        return new Event(Type.ACCEPTED, orderID, 0, price, qty);
    }

    /**
     * Creates an event indicating that a trade occurred.
     *
     * @param takerId ID of the incoming order
     * @param makerId ID of the resting order that was matched
     * @param price   execution price
     * @param qty     traded quantity
     * @return a TRADE event
     */
    static Event trade(long takerId, long makerId, long price, long qty) {
        return new Event(Type.TRADE, takerId, makerId, price, qty);
    }

    /**
     * Creates an event indicating that an order was cancelled.
     *
     * @param orderId ID of the cancelled order
     * @return a CANCELLED event
     */
    static Event cancelled(long orderId) {
        return new Event(Type.CANCELLED, orderId, 0, 0, 0);
    }

    /**
     * Creates an event indicating that an order was rejected.
     *
     * @param orderId ID of the rejected order
     * @return a REJECTED event
     */
    static Event rejected(long orderId) {
        return new Event(Type.REJECTED, orderId, 0, 0, 0);
    }
}